@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label text-white mb-1">Current Warehouse</label>
    <select class="form-select form-select-sm" value="@WarehouseState.SelectedWarehouseId" @onchange="OnWarehouseSelected">
        @foreach (var wh in Services.WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var selectedId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(selectedId))
        {
            WarehouseState.SetWarehouse(selectedId);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _handler;
    }
}

